type RenderOptions = {
  priceDisplay: "visible" | "hidden";
  delivery: "preview" | "email";
};

function renderInvoice(
  invoice,
  options: RenderOptions,
) {
  if (options.delivery === "email") {
    return emailInvoice(invoice, options);
  }

  return previewInvoice(invoice, options);
}

